import type { SVGProps } from "react";
import { glyphs, type GlyphName } from "./glyphs";

type IconProps = SVGProps<SVGSVGElement> & { size?: number };

function Svg({ size = 16, children, ...rest }: IconProps) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      aria-hidden="true"
      focusable="false"
      style={{ display: "block", flexShrink: 0 }}
      {...rest}
    >
      {children}
    </svg>
  );
}

const outline = {
  fill: "none",
  stroke: "currentColor",
  strokeLinecap: "round",
  strokeLinejoin: "round",
  overflow: "visible",
} as const;

export function Glyph({ name, size = 24, ...rest }: IconProps & { name: GlyphName }) {
  const glyph = glyphs[name];
  const isOutline = "stroke" in glyph;
  return (
    <Svg viewBox="0 0 32 32" size={size} {...rest}>
      {isOutline ? (
        <path d={glyph.d} fill="none" stroke="currentColor" strokeWidth={2} />
      ) : (
        <path d={glyph.d} fill="currentColor" />
      )}
    </Svg>
  );
}

